INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-03' FROM countries WHERE name_en = 'Oman';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Phased Peppol 5-corner clearance/reporting model (Fawtara), rolling out August 2026 – August 2028', 'This deep-dive page reflects publicly available OTA guidance and industry reporting as of early August 2026 and is provided for general awareness, not legal or tax advice. Oman''s e-invoicing rollout is still in its early phases and selection criteria for each wave are OTA-determined — confirm your business''s specific phase and requirements directly with the Oman Tax Authority before building against any date here.', 'Oman''s e-invoicing mandate is genuinely new — announced in October 2025 and rolling out in four dated phases through August 2028 via the OTA''s Fawtara platform, rather than a decade-old system like several of this tracker''s other entries. The first wave, covering roughly the 100 largest taxpayers, goes live in August 2026; full domestic B2B coverage, including SMEs, follows by August 2027; government-counterparty transactions complete the rollout by August 2028.', 'Fawtara uses PINT-OM (Peppol International Invoice — Oman), a national specialisation of the Peppol BIS Billing standard, built on XML UBL 2.1. B2C invoices additionally require a QR code. There is no separate proprietary Omani schema to learn beyond this Peppol-based specification.', 'Oman has adopted a Peppol five-corner model: invoices route through an OTA-Accredited Service Provider (ASP) on both the supplier and buyer side, with the OTA itself acting as the fifth corner, receiving a real-time report and acknowledgment alongside the buyer-side delivery — closer to the UAE''s decentralised ASP model than to Saudi Arabia''s centralised ZATCA clearance portal.', 'Getting compliant here means figuring out which phase applies to you, then arranging Accredited Service Provider access well ahead of that date — Oman''s rollout gives affected businesses real advance notice via direct OTA outreach and readiness surveys, rather than a single fixed date applying to everyone at once.', 'The OTA has not yet published a specific fine schedule for e-invoicing non-compliance as of this writing — Oman''s existing VAT Law penalty framework would presumably apply in the interim, but no e-invoicing-specific figures have been confirmed publicly.', 'Oman is rolling out mandatory e-invoicing in four dated phases via the OTA''s Fawtara platform, a Peppol five-corner model with real-time tax authority reporting. The first wave — roughly the 100 largest taxpayers — goes live in August 2026, expanding to all VAT-registered businesses by August 2027 and government-counterparty transactions by August 2028. This is one of the most concretely dated, imminent e-invoicing mandates in the Middle East region today.', '🇴🇲' FROM countries WHERE name_en = 'Oman';
