INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Oman';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & standard', '[["Standard", "PINT-OM (Peppol International Invoice — Oman), a national specialisation of Peppol BIS Billing"], ["Base format", "XML, UBL 2.1"], ["B2C requirement", "Mandatory QR code on every consumer-facing invoice"], ["Legal basis", "Oman Tax Authority regulations under the VAT Law, implemented via the Fawtara programme"]]', 'There''s no separate proprietary Omani schema to learn — PINT-OM is a Peppol-based specification, the same family of standard used by the UAE and several Asia-Pacific countries in this tracker.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Oman';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Identifiers & registration', '[["Access route", "An OTA-Accredited Service Provider (ASP) — no direct government portal upload"], ["ASP registration opened", "May 2026"], ["Developer/test portal opened", "February 2026"], ["Governing body", "Oman Tax Authority (OTA)"]]', 'Like the UAE, Oman routes every invoice through a certified intermediary rather than a direct government clearance portal — appointing an ASP is the practical first step for any affected business.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Oman';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Mandatory content', '[["Core model", "Peppol BIS Billing 3.0 base fields, extended by the PINT-OM data dictionary"], ["Reporting window", "Near real-time submission to the OTA alongside buyer delivery"], ["B2C invoices", "Must additionally carry a QR code"]]', 'The near-real-time reporting requirement puts Oman structurally closer to a clearance model than a pure post-audit one, even though the OTA itself never blocks or approves an invoice the way Saudi Arabia''s ZATCA portal does.', NULL);
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 0, 'pills' FROM countries WHERE name_en = 'Oman';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'The five corners', 'Every invoice under Fawtara moves through the same five-corner sequence:', 'The OTA''s acknowledgment (corner 5) arrives in parallel with delivery to the buyer, not as a separate later step — this is what makes the model near-real-time rather than a simple 4-corner exchange with after-the-fact reporting bolted on.');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 0, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Supplier issues invoice');
