INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Buyer receives + OTA notified');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Oman';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What each phase actually requires', '[["Phase 1 (Aug 2026)", "Roughly the 100 largest taxpayers, selected by size, transaction volume, sector, geography, and risk profile"], ["Phase 2 (Feb 2027)", "Remaining large taxpayers not covered by Phase 1"], ["Phase 3 (Aug 2027)", "Every remaining VAT-registered taxpayer, including SMEs"], ["Phase 4 (Aug 2028)", "Government entities, as e-invoicing counterparties"]]', 'Unlike a single fixed go-live date, Oman''s rollout gives each wave roughly six to twelve months'' notice — the practical question for most businesses is which phase applies to them, not whether one eventually will.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Oman';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Voluntary participation ahead of your phase', '[["Who can join early", "Any VAT-registered business not yet in a mandatory phase"], ["Why it might make sense", "Getting ASP integration and ERP changes done ahead of a hard deadline, rather than against one"], ["Cost of waiting", "None specific published yet, beyond the general risk of a compressed implementation timeline"]]', 'Oman explicitly allows voluntary early participation for businesses outside the current wave — a lower-pressure way to get compliant infrastructure in place before it''s legally required.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Oman';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📋 No published e-invoicing-specific penalty schedule yet', NULL, NULL, 'As of this writing, the OTA has not published a specific fine structure for e-invoicing non-compliance. Oman''s existing general VAT Law penalty framework would presumably apply in the interim, but no e-invoicing-specific figures — capped or otherwise — have been confirmed publicly.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Oman';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🗓️ A phased rollout built around direct outreach', NULL, NULL, 'Rather than a single surprise deadline, the OTA has directly notified Phase 1 and Phase 2 taxpayers and run technical-readiness surveys (October 2025 for Phase 1, April 2026 for Phase 2) ahead of each go-live — a more consultative rollout style than several other mandates in this tracker.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Oman';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📡 Watch official OTA communications, not just this table', NULL, NULL, 'Because phase selection depends on OTA-specific criteria (size, volume, sector, geography, risk profile) rather than a public revenue threshold, the most reliable way to know your own go-live date is direct notification from the OTA or checking the Fawtara portal directly, not general commentary.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Oman';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Determine which phase applies to your business', 'Check whether the OTA has identified you as a Phase 1 (largest taxpayers) or Phase 2 (remaining large taxpayers) business — if not, you fall under Phase 3''s universal 2027 requirement by default.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Oman';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Appoint an Accredited Service Provider (ASP)', 'Every business needs a certified ASP to issue and receive Fawtara e-invoices — registration opened in May 2026, so this is the practical first infrastructure decision to make.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Oman';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Prepare ERP or invoicing systems for structured output', 'Confirm your systems can produce PINT-OM/UBL 2.1-compliant invoices, including a QR code for any B2C invoices, before your phase''s go-live date.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Oman';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Consider voluntary early participation', 'If you''re not yet in a mandatory phase, getting ASP and ERP work done ahead of a hard deadline avoids a compressed, last-minute implementation.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Oman';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Track official OTA communications directly', 'Phase selection depends on OTA-specific criteria, not a single public threshold — direct notifications and the Fawtara portal are more reliable than general industry commentary.');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://tms.taxoman.gov.om/portal/e-invoicing', 0 FROM countries WHERE name_en = 'Oman';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'Oman Tax Authority — e-Invoicing (Fawtara)');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://tms.taxoman.gov.om/portal/service-provider', 1 FROM countries WHERE name_en = 'Oman';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'Oman Tax Authority — Service Provider Registration');
